def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = {}
    rejected = []
    history = []

    pow10 = (
        1, 10, 100, 1000, 10000, 100000, 1000000,
        10000000, 100000000, 1000000000
    )

    def parse_amount(s):
        if not s:
            return None

        for ch in s:
            if ch < '0' or ch > '9':
                return None

        n = len(s)
        i = 0
        while i < n and s[i] == '0':
            i += 1

        if i == n:
            return 0

        value = 0
        while i < n:
            j = i + 9
            if j > n:
                j = n
            value = value * pow10[j - i] + int(s[i:j])
            i = j

        return value

    for idx, op in enumerate(ops):
        parts = op.split()
        ok = len(parts) > 0

        if ok:
            verb = parts[0]

            if verb == "open":
                if len(parts) == 3:
                    account = parts[1]
                    amount = parse_amount(parts[2])

                    if account not in balances and amount is not None:
                        balances[account] = amount
                        frozen[account] = False
                        history.append(("open", account))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "deposit":
                if len(parts) == 3:
                    account = parts[1]
                    amount = parse_amount(parts[2])

                    if (
                        account in balances
                        and amount is not None
                        and amount > 0
                    ):
                        balances[account] += amount
                        history.append(("deposit", account, amount))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "withdraw":
                if len(parts) == 3:
                    account = parts[1]
                    amount = parse_amount(parts[2])

                    if (
                        account in balances
                        and not frozen[account]
                        and amount is not None
                        and amount > 0
                        and balances[account] >= amount
                    ):
                        balances[account] -= amount
                        history.append(("withdraw", account, amount))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "transfer":
                if len(parts) == 4:
                    source = parts[1]
                    target = parts[2]
                    amount = parse_amount(parts[3])

                    if (
                        source != target
                        and source in balances
                        and target in balances
                        and not frozen[source]
                        and amount is not None
                        and amount > 0
                        and balances[source] >= amount
                    ):
                        balances[source] -= amount
                        balances[target] += amount
                        history.append(("transfer", source, target, amount))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "freeze":
                if len(parts) == 2:
                    account = parts[1]

                    if account in balances and not frozen[account]:
                        frozen[account] = True
                        history.append(("freeze", account))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "unfreeze":
                if len(parts) == 2:
                    account = parts[1]

                    if account in balances and frozen[account]:
                        frozen[account] = False
                        history.append(("unfreeze", account))
                    else:
                        ok = False
                else:
                    ok = False

            elif verb == "undo":
                if len(parts) == 1:
                    if not history:
                        ok = False
                    else:
                        record = history.pop()
                        kind = record[0]

                        if kind == "open":
                            account = record[1]
                            del balances[account]
                            del frozen[account]

                        elif kind == "deposit":
                            account = record[1]
                            amount = record[2]
                            balances[account] -= amount

                        elif kind == "withdraw":
                            account = record[1]
                            amount = record[2]
                            balances[account] += amount

                        elif kind == "transfer":
                            source = record[1]
                            target = record[2]
                            amount = record[3]
                            balances[source] += amount
                            balances[target] -= amount

                        elif kind == "freeze":
                            account = record[1]
                            frozen[account] = False

                        elif kind == "unfreeze":
                            account = record[1]
                            frozen[account] = True
                else:
                    ok = False

            else:
                ok = False

        if not ok:
            rejected.append(idx)

    return balances, rejected
